package edu.pe.cibertec.saibm.inventario;
import static org.assertj.core.api.Assertions.assertThat; import com.fasterxml.jackson.databind.ObjectMapper; import com.fasterxml.jackson.databind.json.JsonMapper; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import java.time.*; import java.util.concurrent.*; import java.util.stream.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.boot.test.context.TestConfiguration; import org.springframework.boot.testcontainers.service.connection.ServiceConnection; import org.springframework.context.annotation.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.junit.jupiter.*; import org.testcontainers.postgresql.PostgreSQLContainer; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.infrastructure.persistence.InventoryJpaAdapter; import edu.pe.cibertec.saibm.inventario.infrastructure.config.InventarioConfig;
@DataJpaTest(properties="spring.jpa.hibernate.ddl-auto=validate") @Testcontainers @Import({InventoryJpaAdapter.class,InventarioConfig.class,InventoryPostgresTest.JsonConfig.class}) @org.springframework.transaction.annotation.Transactional(propagation=org.springframework.transaction.annotation.Propagation.NOT_SUPPORTED) class InventoryPostgresTest { @Container @ServiceConnection static final PostgreSQLContainer PG=new PostgreSQLContainer("postgres:16.9-alpine"); @DynamicPropertySource static void db(DynamicPropertyRegistry r){r.add("spring.flyway.enabled",()->true);} @Autowired JdbcTemplate sql; @Autowired @Qualifier("inventory") InventoryUseCase use;
 @BeforeEach void seed(){sql.update("delete from inventory_inbox");sql.update("delete from inventory_outbox");sql.update("delete from inventory_movements");sql.update("delete from inventory_holds");sql.update("delete from inventory_stock");sql.update("insert into inventory_stock(book_id,total_stock,available_stock) values ('book-1',1,1)");}
 @Test void concurrentHoldsHaveOneWinnerAndNonNegativeStock() throws Exception {var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(IntStream.range(0,2).mapToObj(i->(Callable<Boolean>)()->use.hold("book-1",1,Instant.now().plusSeconds(60),"k"+i,"c").accepted()).toList());assertThat(results.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isEqualTo(1);assertThat(sql.queryForObject("select available_stock from inventory_stock where book_id='book-1'",Integer.class)).isZero();assertThat(sql.queryForObject("select count(*) from inventory_outbox",Integer.class)).isEqualTo(2);}finally{pool.shutdownNow();}}
 @TestConfiguration static class JsonConfig {@Bean ObjectMapper objectMapper(){return JsonMapper.builder().addModule(new JavaTimeModule()).build();}}
}
